// Author: MiYu. Execute supported register, stack, native call and script call instructions with limits.
#include "jass_binary_vm.h"
#include <array>
#include <bit>
#include <climits>
#include <optional>
#include <stdexcept>

namespace war3 {
JassBinaryNativeValue runJass2Function(const JassBinaryProgram& program,const JassBinaryIndex& index,const std::string& name,const JassBinaryHost& host,std::span<const JassBinaryNativeValue> arguments,size_t stepLimit){
    using Value=JassBinaryNativeValue;struct Frame{size_t start=0,pc=0,end=0,base=0,argc=0;std::array<Value,256> regs{};std::map<std::string,Value> locals;std::map<std::string,std::map<std::uint32_t,Value>> arrays;};std::vector<Frame> frames;std::vector<Value> stack(arguments.begin(),arguments.end());auto symbol=[&](std::uint32_t id)->const std::string&{if(!id || id>program.symbols.size())throw std::runtime_error("Invalid 2SAJ symbol");return program.symbols[id-1];};auto enter=[&](const std::string& function){auto found=index.functions.find(function);if(found==index.functions.end() || frames.size()>=256)throw std::runtime_error("Missing or excessive 2SAJ function: "+function);auto [start,end]=found->second;if(start>=end || end>=program.instructions.size())throw std::runtime_error("Invalid 2SAJ function bounds");size_t count=0;while(start+1+count<end && program.instructions[start+1+count].opcode==8)++count;if(stack.size()<count)throw std::runtime_error("2SAJ function arguments missing");Frame frame;frame.start=start;frame.pc=start+1;frame.end=end;frame.base=stack.size()-count;frame.argc=count;frames.push_back(std::move(frame));};enter(name);size_t steps=0;Value result;
    while(!frames.empty()){if(++steps>stepLimit)throw std::runtime_error("2SAJ instruction budget exceeded");auto& f=frames.back();if(f.pc>=f.end)throw std::runtime_error("2SAJ function did not return");auto ins=program.instructions[f.pc++];auto& reg=f.regs[ins.r1];switch(ins.opcode){
        case 5:if(ins.r1<4 || ins.r1>13 || !f.locals.emplace(symbol(ins.operand),Value{ins.r1,0,{}}).second)throw std::runtime_error("Invalid 2SAJ local");break;
        case 8:{auto arg=f.base+f.argc-size_t(ins.r2);if(!ins.r2 || ins.r2>f.argc || arg>=stack.size())throw std::runtime_error("Invalid 2SAJ function argument");auto value=stack[arg];if(value.type!=ins.r1 && !(value.type==2 && !value.bits && (ins.r1==6 || ins.r1==7)))throw std::runtime_error("Mismatched 2SAJ function argument");value.type=ins.r1;if(!f.locals.emplace(symbol(ins.operand),value).second)throw std::runtime_error("Duplicate 2SAJ function argument");break;}
        case 11:if(ins.r1>stack.size()-f.base)throw std::runtime_error("2SAJ stack underflow");stack.resize(stack.size()-ins.r1);break;
        case 12:if(!((ins.r2==0 && !ins.operand) || ins.r2==2 || (ins.r2>=4 && ins.r2<=8)))throw std::runtime_error("Unsupported 2SAJ literal type: "+std::to_string(ins.r2)+" at "+std::to_string(f.pc-1));if((ins.r2==2 && ins.operand) || (ins.r2==6 && ins.operand>program.symbols.size()))throw std::runtime_error("Invalid 2SAJ literal value");reg={ins.r2,ins.operand,{}};break;
        case 13:reg=f.regs[ins.r2];break;
        case 14:{auto local=f.locals.find(symbol(ins.operand));if(local!=f.locals.end())reg=local->second;else{if(!host.globalRead)throw std::runtime_error("2SAJ global callback missing");reg=host.globalRead(symbol(ins.operand));}break;}
        case 16:{auto indexValue=f.regs[ins.r2];if(indexValue.type!=4 || ins.r3<4 || ins.r3>8)throw std::runtime_error("Invalid 2SAJ array read");auto& arrayName=symbol(ins.operand);auto local=f.locals.find(arrayName);if(local!=f.locals.end()){if(local->second.type!=ins.r3+5)throw std::runtime_error("Mismatched 2SAJ local array");reg={ins.r3,0,{}};if(indexValue.bits<8192){auto array=f.arrays.find(arrayName);if(array!=f.arrays.end())if(auto it=array->second.find(indexValue.bits);it!=array->second.end())reg=it->second;}}else if(indexValue.bits>=8192)reg={ins.r3,0,{}};else{if(!host.arrayRead)throw std::runtime_error("2SAJ array read callback missing");reg=host.arrayRead(arrayName,indexValue.bits,ins.r3);if(reg.type!=ins.r3)throw std::runtime_error("Mismatched 2SAJ global array read");}break;}
        case 17:{auto local=f.locals.find(symbol(ins.operand));if(local==f.locals.end()){if(!host.globalWrite)throw std::runtime_error("2SAJ global write callback missing");host.globalWrite(symbol(ins.operand),reg);break;}auto type=local->second.type;if(reg.type!=type && !(reg.type==2 && !reg.bits && (type==6 || type==7)))throw std::runtime_error("Mismatched 2SAJ local assignment");local->second=reg;local->second.type=type;break;}
        case 18:{auto indexValue=reg,value=f.regs[ins.r2];if(indexValue.type!=4 || (value.type!=2 && (value.type<4 || value.type>8)))throw std::runtime_error("Invalid 2SAJ array write");auto& arrayName=symbol(ins.operand);auto local=f.locals.find(arrayName);if(local!=f.locals.end()){auto elementType=std::uint8_t(local->second.type-5);if(local->second.type<9 || local->second.type>13 || (value.type!=elementType && !(value.type==2 && !value.bits && (elementType==6 || elementType==7))))throw std::runtime_error("Mismatched 2SAJ local array");value.type=elementType;if(indexValue.bits<8192)f.arrays[arrayName].insert_or_assign(indexValue.bits,value);}else if(indexValue.bits<8192){if(!host.arrayWrite)throw std::runtime_error("2SAJ array write callback missing");host.arrayWrite(arrayName,indexValue.bits,value);}break;}
        case 19:if(stack.size()>=262144)throw std::runtime_error("2SAJ stack budget exceeded");stack.push_back(reg);break;
        case 20:if(stack.size()<=f.base)throw std::runtime_error("2SAJ stack underflow");reg=stack.back();stack.pop_back();break;
        case 21:{if(!host.nativeArity || !host.nativeCall)throw std::runtime_error("2SAJ native callback missing");auto& native=symbol(ins.operand);auto count=host.nativeArity(native);if(count>stack.size()-f.base)throw std::runtime_error("2SAJ native arguments missing: "+native);auto value=host.nativeCall(native,std::span<const Value>(stack).last(count));stack.resize(stack.size()-count);f.regs[0]=std::move(value);break;}
        case 22:enter(symbol(ins.operand));break;
        case 23:if(reg.type!=4)throw std::runtime_error("Invalid 2SAJ integer conversion");reg={5,jass::Real::fromInteger(std::bit_cast<std::int32_t>(reg.bits)).bits(),{}};break;
        case 24:case 25:{auto left=f.regs[ins.r2],right=f.regs[ins.r3];if(left.type!=8 || right.type!=8)throw std::runtime_error("Invalid 2SAJ boolean operands");reg={8,std::uint32_t(ins.opcode==24?(left.bits && right.bits):(left.bits || right.bits)),{}};break;}
        case 26:case 27:case 28:case 29:case 30:case 31:case 32:case 33:case 34:case 35:{auto left=f.regs[ins.r2],right=f.regs[ins.r3];if((ins.opcode==26 || ins.opcode==27) && ((left.type==6 || left.type==2) && (right.type==6 || right.type==2))){auto text=[&](const Value& v)->std::optional<std::string_view>{if(v.type==2)return {};if(v.text)return *v.text;if(!v.bits)return {};return symbol(v.bits);};auto equal=text(left)==text(right);reg={8,std::uint32_t(ins.opcode==26?equal:!equal),{}};break;}if((ins.opcode==26 || ins.opcode==27) && (((left.type==7 || left.type==2) && (right.type==7 || right.type==2)) || (left.type==8 && right.type==8))){bool equal=left.bits==right.bits;reg={8,std::uint32_t(ins.opcode==26?equal:!equal),{}};break;}if(ins.opcode==32 && (left.type==6 || left.type==2) && (right.type==6 || right.type==2)){auto text=[&](const Value& v)->std::string_view{if(v.type==2)return {};if(v.text)return *v.text;if(!v.bits)return {};return symbol(v.bits);};auto a=text(left),b=text(right);if(a.size()>16*1024*1024 || b.size()>16*1024*1024-a.size())throw std::runtime_error("2SAJ string budget exceeded");auto combined=std::make_shared<std::string>(a);combined->append(b);reg={6,0,std::move(combined)};break;}if((left.type!=4 && left.type!=5) || (right.type!=4 && right.type!=5))throw std::runtime_error("Unsupported 2SAJ numeric operands");bool compare=ins.opcode<=31;if(left.type==5 || right.type==5){auto a=left.type==5?jass::Real::fromBits(left.bits):jass::Real::fromInteger(std::bit_cast<std::int32_t>(left.bits));auto b=right.type==5?jass::Real::fromBits(right.bits):jass::Real::fromInteger(std::bit_cast<std::int32_t>(right.bits));if(!compare){if(ins.opcode==35 && !(b.bits()&0x7fffffff))throw std::runtime_error("2SAJ division by zero");auto value=ins.opcode==32?a.add(b):ins.opcode==33?a.subtract(b):ins.opcode==34?a.multiply(b):a.divide(b);reg={5,value.bits(),{}};}else{float x=std::bit_cast<float>(a.bits()),y=std::bit_cast<float>(b.bits());bool value=ins.opcode==26?std::bit_cast<float>(a.subtract(b).bits()&0x7fffffff)<std::bit_cast<float>(0x3a83126fu):ins.opcode==27?a.bits()!=b.bits():ins.opcode==28?x<=y:ins.opcode==29?x>=y:ins.opcode==30?x<y:x>y;reg={8,std::uint32_t(value),{}};}}else{auto a=std::bit_cast<std::int32_t>(left.bits),b=std::bit_cast<std::int32_t>(right.bits);if(compare){bool value=ins.opcode==26?a==b:ins.opcode==27?a!=b:ins.opcode==28?a<=b:ins.opcode==29?a>=b:ins.opcode==30?a<b:a>b;reg={8,std::uint32_t(value),{}};}else{if(ins.opcode==35 && (!b || (a==INT32_MIN && b==-1)))throw std::runtime_error("Invalid 2SAJ integer division");auto value=ins.opcode==32?left.bits+right.bits:ins.opcode==33?left.bits-right.bits:ins.opcode==34?left.bits*right.bits:std::bit_cast<std::uint32_t>(a/b);reg={4,value,{}};}}break;}
        case 37:if(reg.type==4)reg.bits=0u-reg.bits;else if(reg.type==5)reg.bits^=0x80000000u;else throw std::runtime_error("Invalid 2SAJ negate");break;
        case 38:if(reg.type!=8)throw std::runtime_error("Invalid 2SAJ boolean negation");reg.bits=!reg.bits;break;
        case 39:result=f.regs[0];frames.pop_back();if(!frames.empty())frames.back().regs[0]=result;break;
        case 40:break;
        case 41:case 42:case 43:{bool branch=ins.opcode==43 || (ins.opcode==41?reg.bits!=0:reg.bits==0);if(branch){auto target=index.labels.find(ins.operand);if(target==index.labels.end() || target->second<=f.start || target->second>=f.end)throw std::runtime_error("Invalid 2SAJ jump");f.pc=target->second;}break;}
        default:throw std::runtime_error("Unsupported 2SAJ execution opcode: "+std::to_string(ins.opcode));}}
    return result;
}
}
